package jlsm.engine.cluster;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Tests for {@link NodeAddress} record validation and value semantics.
 */
class NodeAddressTest {

    @Test
    void validConstruction() {
        var addr = new NodeAddress("node-1", "localhost", 8080);
        assertEquals("node-1", addr.nodeId());
        assertEquals("localhost", addr.host());
        assertEquals(8080, addr.port());
    }

    @Test
    void nullNodeIdThrows() {
        assertThrows(NullPointerException.class, () -> new NodeAddress(null, "localhost", 8080));
    }

    @Test
    void nullHostThrows() {
        assertThrows(NullPointerException.class, () -> new NodeAddress("n1", null, 8080));
    }

    @Test
    void emptyNodeIdThrows() {
        assertThrows(IllegalArgumentException.class, () -> new NodeAddress("", "localhost", 8080));
    }

    @Test
    void emptyHostThrows() {
        assertThrows(IllegalArgumentException.class, () -> new NodeAddress("n1", "", 8080));
    }

    @Test
    void portZeroThrows() {
        assertThrows(IllegalArgumentException.class, () -> new NodeAddress("n1", "localhost", 0));
    }

    @Test
    void portNegativeThrows() {
        assertThrows(IllegalArgumentException.class, () -> new NodeAddress("n1", "localhost", -1));
    }

    @Test
    void portAbove65535Throws() {
        assertThrows(IllegalArgumentException.class, () -> new NodeAddress("n1", "localhost", 65536));
    }

    @Test
    void portBoundaryMin() {
        var addr = new NodeAddress("n1", "h", 1);
        assertEquals(1, addr.port());
    }

    @Test
    void portBoundaryMax() {
        var addr = new NodeAddress("n1", "h", 65535);
        assertEquals(65535, addr.port());
    }

    @Test
    void equalityAndHashCode() {
        var a = new NodeAddress("n1", "host", 80);
        var b = new NodeAddress("n1", "host", 80);
        assertEquals(a, b);
        assertEquals(a.hashCode(), b.hashCode());
    }

    @Test
    void inequalityOnDifferentFields() {
        var a = new NodeAddress("n1", "host", 80);
        assertNotEquals(a, new NodeAddress("n2", "host", 80));
        assertNotEquals(a, new NodeAddress("n1", "other", 80));
        assertNotEquals(a, new NodeAddress("n1", "host", 81));
    }
}

package jlsm.engine.cluster;

import org.junit.jupiter.api.Test;

import java.time.Duration;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Tests for {@link ClusterConfig} record validation and builder defaults.
 */
class ClusterConfigTest {

    @Test
    void builderDefaults() {
        var config = ClusterConfig.builder().build();
        assertEquals(ClusterConfig.DEFAULT_GRACE_PERIOD, config.gracePeriod());
        assertEquals(ClusterConfig.DEFAULT_PROTOCOL_PERIOD, config.protocolPeriod());
        assertEquals(ClusterConfig.DEFAULT_PING_TIMEOUT, config.pingTimeout());
        assertEquals(ClusterConfig.DEFAULT_INDIRECT_PROBES, config.indirectProbes());
        assertEquals(ClusterConfig.DEFAULT_PHI_THRESHOLD, config.phiThreshold());
        assertEquals(ClusterConfig.DEFAULT_CONSENSUS_QUORUM_PERCENT, config.consensusQuorumPercent());
    }

    @Test
    void builderOverrides() {
        var config = ClusterConfig.builder()
                .gracePeriod(Duration.ofMinutes(5))
                .protocolPeriod(Duration.ofSeconds(2))
                .pingTimeout(Duration.ofMillis(250))
                .indirectProbes(5)
                .phiThreshold(10.0)
                .consensusQuorumPercent(50)
                .build();
        assertEquals(Duration.ofMinutes(5), config.gracePeriod());
        assertEquals(Duration.ofSeconds(2), config.protocolPeriod());
        assertEquals(Duration.ofMillis(250), config.pingTimeout());
        assertEquals(5, config.indirectProbes());
        assertEquals(10.0, config.phiThreshold());
