 20→ * handler — no serialization or networking occurs. Thread-safe via concurrent data structures.
 21→ *
 22→ * <p>
 23→ * Side effects: Modifies the static transport registry on creation and {@link #close()}.
 24→ *
 25→ * <p>
 26→ * Governed by: {@code .decisions/transport-abstraction-design/adr.md}
 27→ */
 28→public final class InJvmTransport implements ClusterTransport {
 29→
 30→    private static final ConcurrentHashMap<NodeAddress, InJvmTransport> REGISTRY =
 31→            new ConcurrentHashMap<>();
 32→
 33→    private final NodeAddress localAddress;
 34→    private final ConcurrentHashMap<MessageType, MessageHandler> handlers =
 35→            new ConcurrentHashMap<>();
 36→    private volatile boolean closed;
 37→
 38→    /**
 39→     * Creates and registers a new in-JVM transport for the given local address.
 40→     *
 41→     * @param localAddress the address of the local node; must not be null
 42→     * @throws IllegalArgumentException if the address is already registered
 43→     */
 44→    public InJvmTransport(NodeAddress localAddress) {
 45→        Objects.requireNonNull(localAddress, "localAddress must not be null");
 46→        this.localAddress = localAddress;
 47→        final var previous = REGISTRY.putIfAbsent(localAddress, this);
 48→        if (previous != null) {
 49→            throw new IllegalArgumentException(
 50→                    "Address already registered: " + localAddress);
 51→        }
 52→    }
 53→
 54→    @Override
 55→    public void send(NodeAddress target, Message msg) throws IOException {
 56→        Objects.requireNonNull(target, "target must not be null");
 57→        Objects.requireNonNull(msg, "msg must not be null");
 58→        if (closed) {
 59→            throw new IOException("Transport is closed");
 60→        }
 61→        final var targetTransport = REGISTRY.get(target);
 62→        if (targetTransport == null) {
 63→            throw new IOException("No transport registered for target: " + target);
 64→        }
 65→        final var handler = targetTransport.handlers.get(msg.type());
 66→        if (handler != null) {
 67→            handler.handle(localAddress, msg);
 68→        }
 69→        // Fire-and-forget: no handler means silent drop
 70→    }
 71→
 72→    @Override
 73→    public CompletableFuture<Message> request(NodeAddress target, Message msg) {
 74→        Objects.requireNonNull(target, "target must not be null");
 75→        Objects.requireNonNull(msg, "msg must not be null");
 76→        if (closed) {
 77→            return CompletableFuture.failedFuture(new IOException("Transport is closed"));
 78→        }
 79→        final var targetTransport = REGISTRY.get(target);
 80→        if (targetTransport == null) {
 81→            return CompletableFuture.failedFuture(
 82→                    new IOException("No transport registered for target: " + target));
 83→        }
 84→        final var handler = targetTransport.handlers.get(msg.type());
 85→        if (handler == null) {
 86→            return CompletableFuture.failedFuture(
 87→                    new IOException("No handler registered for type: " + msg.type()));
 88→        }
 89→        return handler.handle(localAddress, msg);
 90→    }
 91→
 92→    @Override
 93→    public void registerHandler(MessageType type, MessageHandler handler) {
 94→        Objects.requireNonNull(type, "type must not be null");
 95→        Objects.requireNonNull(handler, "handler must not be null");
 96→        assert !closed : "Cannot register handler on closed transport";
 97→        handlers.put(type, handler);
 98→    }
 99→
100→    @Override
101→    public void close() {
102→        if (closed) {
103→            return;
104→        }
105→        closed = true;
106→        REGISTRY.remove(localAddress);
107→        handlers.clear();
108→    }
109→
110→    /**
111→     * Returns the handler registered for the given type, or null if none.
112→     * Package-private for testing.
113→     *
114→     * @param type the message type
115→     * @return the registered handler, or null
116→     */
117→    MessageHandler handler(MessageType type) {
118→        return handlers.get(type);
119→    }
120→
121→    /**
122→     * Clears the global registry. For test cleanup only.
123→     */
124→    static void clearRegistry() {
125→        REGISTRY.clear();
126→    }
127→}
